source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    width = len(grid[0])
    for i, row in enumerate(grid):
        if row[-1] != background:
            continue
        counts = Counter(v for v in row if v != background)
        if not counts:
            continue
        color = counts.most_common(1)[0][0]
        target = {j for j, v in enumerate(row) if v == color}
        best = None
        for k, candidate in enumerate(grid):
            if k == i or candidate[-1] != color:
                continue
            other = {j for j, v in enumerate(candidate) if v == color}
            union = target | other
            score = len(target & other) / len(union) if union else 0
            if score >= 0.60 and (best is None or score > best[0]):
                best = (score, candidate)
        if best is not None:
            candidate = best[1]
            for j in range(width):
                if row[j] == background and candidate[j] == color:
                    out[i][j] = 1
    return out
